#!/bin/sh
# Generated by Claude Code 2.1.263 (claude-opus-5[1m])
#
# Fetch the third-party sources needed for the Android/Quest build.
# Every dependency is pinned. Sources land in android/deps/src and are
# not tracked by git.

set -e

DEPS_DIR=$(cd "$(dirname "$0")" && pwd)
SRC_DIR="$DEPS_DIR/src"

SDL_REPO=https://github.com/libsdl-org/SDL.git
SDL_TAG=release-2.32.4

GL4ES_REPO=https://github.com/ptitSeb/gl4es.git
GL4ES_COMMIT=c9895df34cd466c23bc60c2bd3db3d87e98fcbe7

# Shallow-clone a repo at a tag, or fetch a single commit.
clone_at()
{
    name=$1
    repo=$2
    ref=$3

    dir="$SRC_DIR/$name"

    if [ -d "$dir/.git" ]; then
        echo "$name: present"
        return
    fi

    echo "$name: fetching $ref"

    mkdir -p "$dir"
    git -C "$dir" init -q
    git -C "$dir" remote add origin "$repo"
    git -C "$dir" fetch -q --depth 1 origin "$ref"
    git -C "$dir" checkout -q FETCH_HEAD
}

mkdir -p "$SRC_DIR"

clone_at SDL   "$SDL_REPO"   "$SDL_TAG"
clone_at gl4es "$GL4ES_REPO" "$GL4ES_COMMIT"

echo "deps: ok"
